import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.reduce.js";
import { ref, computed, onMounted, onUnmounted } from 'vue';
import dayjs from 'dayjs';
import ChartBase from '@/components/ChartBase.vue';
import { screenDashboard, screenApplyTrend, screenJobRanking, screenJobTypeDistribution, screenCollegeDistribution, screenCompanyAuthDistribution, screenApplySuccess, screenRecentApplies } from '@/api/publicStats';
import { useDictStore } from '@/stores/dict';
import { APPLY_STATE_MAP, INTERVIEW_STATE_MAP, COMPANY_AUTH_STATE_MAP } from '@/utils/enums';
import { formatDateTime } from '@/utils/format';
export default {
  __name: 'DataScreen',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const dictStore = useDictStore();
    const loading = ref(false);
    const loadError = ref(false);
    const trendDays = ref(14);
    const updateTime = ref('');
    const now = ref(dayjs());
    const summary = ref({});
    const trend = ref([]);
    const ranking = ref([]);
    const jobTypes = ref([]);
    const colleges = ref([]);
    const companyAuth = ref([]);
    const successData = ref({
      total: 0,
      success: 0,
      rate: 0,
      jobTypeRates: []
    });
    const recent = ref([]);
    const jobTypeDict = ref([]);
    const fmt = n => Number(n || 0).toLocaleString('zh-CN');
    let refreshTimer = null;
    let clockTimer = null;

    /* ---------------- 数据加载 ---------------- */
    async function loadAll() {
      loading.value = true;
      loadError.value = false;
      try {
        const [s, r, t, jt, c, ca, su, re] = await Promise.all([screenDashboard(), screenJobRanking({
          limit: 10
        }), screenApplyTrend({
          days: trendDays.value
        }), screenJobTypeDistribution(), screenCollegeDistribution({
          limit: 10
        }), screenCompanyAuthDistribution(), screenApplySuccess(), screenRecentApplies({
          limit: 8
        })]);
        summary.value = s || {};
        ranking.value = r || [];
        trend.value = t || [];
        jobTypes.value = jt || [];
        colleges.value = c || [];
        companyAuth.value = ca || [];
        successData.value = su || {
          total: 0,
          success: 0,
          rate: 0,
          jobTypeRates: []
        };
        recent.value = re || [];
        updateTime.value = dayjs().format('YYYY-MM-DD HH:mm:ss');
      } catch (e) {
        // 公开接口异常时不阻塞大屏展示，保留上次数据
        loadError.value = true;
      } finally {
        loading.value = false;
      }
    }
    async function changeDays(d) {
      trendDays.value = d;
      try {
        trend.value = (await screenApplyTrend({
          days: d
        })) || [];
      } catch (e) {
        // 忽略
      }
    }
    async function loadDict() {
      try {
        jobTypeDict.value = (await dictStore.load('job_type')) || [];
      } catch (e) {
        jobTypeDict.value = [];
      }
    }

    /* ---------------- 工具 ---------------- */
    const jobTypeLabel = code => {
      const item = jobTypeDict.value.find(d => d.dictCode === code);
      return item ? item.dictLabel : code || '未知';
    };
    const stateLabel = state => APPLY_STATE_MAP[state]?.label || state || '-';
    const stateCount = state => Number(summary.value.applyStateCount?.[state] || 0);
    const pct = (part, total) => {
      const t = Number(total || 0);
      if (!t) return '0%';
      return (Number(part || 0) / t * 100).toFixed(1) + '%';
    };
    const tagClass = state => `tag-${state || 'pending'}`;
    const TAG_COLORS = {
      pending: '#909399',
      interview: '#faad14',
      rejected: '#f56c6c',
      agreement: '#2f6fed',
      hired: '#18a058',
      withdrawn: '#c0c4cc'
    };
    const tagColor = state => TAG_COLORS[state] || '#909399';

    /* ---------------- KPI ---------------- */
    const kpis = computed(() => [{
      label: '学生总数',
      value: summary.value.studentCount,
      sub: '平台注册学生',
      color: '#2f6fed',
      icon: 'User'
    }, {
      label: '企业总数',
      value: summary.value.companyCount,
      sub: `已认证 ${fmt(summary.value.companyAuthedCount)} 家`,
      color: '#8b5cf6',
      icon: 'OfficeBuilding'
    }, {
      label: '岗位总数',
      value: summary.value.jobCount,
      sub: `在线中 ${fmt(summary.value.jobOnlineCount)} 个`,
      color: '#13c2c2',
      icon: 'Briefcase'
    }, {
      label: '投递总数',
      value: summary.value.applyCount,
      sub: `今日新增 +${fmt(summary.value.todayApplyCount)}`,
      color: '#faad14',
      icon: 'Position'
    }, {
      label: '面试安排',
      value: summary.value.interviewCount,
      sub: '累计面试场次',
      color: '#2f6fed',
      icon: 'Calendar'
    }, {
      label: '实习协议',
      value: summary.value.agreementCount,
      sub: `已签署 ${fmt(summary.value.agreementSignedCount)} 份`,
      color: '#18a058',
      icon: 'Files'
    }]);

    /* ---------------- 趋势 ---------------- */
    const trendSum = computed(() => trend.value.reduce((s, t) => s + Number(t.count || 0), 0));
    const trendAvg = computed(() => trend.value.length ? Math.round(trendSum.value / trend.value.length) : 0);
    const trendOption = computed(() => ({
      tooltip: {
        trigger: 'axis'
      },
      grid: {
        left: 48,
        right: 20,
        top: 24,
        bottom: 30
      },
      xAxis: {
        type: 'category',
        boundaryGap: false,
        data: trend.value.map(t => dayjs(t.date).format('MM/DD')),
        axisLine: {
          lineStyle: {
            color: '#e4e7ed'
          }
        },
        axisTick: {
          show: false
        },
        axisLabel: {
          color: '#909399',
          fontSize: 11
        }
      },
      yAxis: {
        type: 'value',
        splitLine: {
          lineStyle: {
            color: '#eef1f6'
          }
        },
        axisLabel: {
          color: '#909399',
          fontSize: 11
        }
      },
      series: [{
        name: '投递量',
        type: 'line',
        smooth: true,
        symbol: 'circle',
        symbolSize: 5,
        showSymbol: true,
        data: trend.value.map(t => Number(t.count || 0)),
        lineStyle: {
          width: 2.5,
          color: '#2f6fed'
        },
        itemStyle: {
          color: '#2f6fed',
          borderColor: '#fff',
          borderWidth: 1.5
        },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0,
            y: 0,
            x2: 0,
            y2: 1,
            colorStops: [{
              offset: 0,
              color: 'rgba(47,111,237,0.25)'
            }, {
              offset: 1,
              color: 'rgba(47,111,237,0)'
            }]
          }
        }
      }]
    }));

    /* ---------------- 环形图 ---------------- */
    function donutOption(items) {
      return {
        tooltip: {
          trigger: 'item',
          formatter: '{b}: {c} ({d}%)'
        },
        legend: {
          bottom: 0,
          icon: 'circle',
          itemWidth: 8,
          itemHeight: 8,
          textStyle: {
            color: '#606266',
            fontSize: 12
          }
        },
        series: [{
          type: 'pie',
          radius: ['46%', '68%'],
          center: ['50%', '44%'],
          avoidLabelOverlap: false,
          itemStyle: {
            borderColor: '#fff',
            borderWidth: 2
          },
          label: {
            show: false
          },
          emphasis: {
            scale: true,
            scaleSize: 4
          },
          data: items
        }]
      };
    }
    const APPLY_COLORS = {
      pending: '#909399',
      interview: '#faad14',
      rejected: '#f56c6c',
      agreement: '#2f6fed',
      hired: '#18a058',
      withdrawn: '#d3dce6'
    };
    const APPLY_ORDER = ['pending', 'interview', 'rejected', 'agreement', 'hired', 'withdrawn'];
    const applyStateOption = computed(() => {
      const map = summary.value.applyStateCount || {};
      return donutOption(APPLY_ORDER.filter(k => map[k] != null).map(k => ({
        name: APPLY_STATE_MAP[k]?.label || k,
        value: Number(map[k] || 0),
        itemStyle: {
          color: APPLY_COLORS[k] || '#2f6fed'
        }
      })));
    });
    const INTERVIEW_COLORS = {
      pending: '#909399',
      confirmed: '#faad14',
      cancelled: '#f56c6c',
      done: '#18a058'
    };
    const INTERVIEW_ORDER = ['pending', 'confirmed', 'cancelled', 'done'];
    const interviewStateOption = computed(() => {
      const map = summary.value.interviewStateCount || {};
      return donutOption(INTERVIEW_ORDER.filter(k => map[k] != null).map(k => ({
        name: INTERVIEW_STATE_MAP[k]?.label || k,
        value: Number(map[k] || 0),
        itemStyle: {
          color: INTERVIEW_COLORS[k] || '#2f6fed'
        }
      })));
    });
    const JOB_TYPE_COLORS = ['#2f6fed', '#13c2c2', '#8b5cf6', '#faad14', '#f56c6c', '#18a058'];
    const jobTypeOption = computed(() => donutOption(jobTypes.value.map((it, i) => ({
      name: jobTypeLabel(it.name),
      value: Number(it.value || 0),
      itemStyle: {
        color: JOB_TYPE_COLORS[i % JOB_TYPE_COLORS.length]
      }
    }))));
    const COMPANY_COLORS = {
      auth: '#18a058',
      pending: '#909399',
      reject: '#f56c6c',
      freeze: '#faad14'
    };
    const companyAuthOption = computed(() => donutOption(companyAuth.value.map(it => ({
      name: COMPANY_AUTH_STATE_MAP[it.name]?.label || it.name || '未知',
      value: Number(it.value || 0),
      itemStyle: {
        color: COMPANY_COLORS[it.name] || '#2f6fed'
      }
    }))));

    /* ---------------- 条形图 ---------------- */
    function hbarOption(items, opts = {}) {
      return {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: opts.left || 150,
          right: opts.right || 60,
          top: 10,
          bottom: 10
        },
        xAxis: {
          type: 'value',
          splitLine: {
            lineStyle: {
              color: '#eef1f6'
            }
          },
          axisLabel: {
            color: '#909399',
            fontSize: 11
          }
        },
        yAxis: {
          type: 'category',
          inverse: true,
          data: items.map(i => i.name),
          axisLine: {
            show: false
          },
          axisTick: {
            show: false
          },
          axisLabel: {
            color: '#606266',
            fontSize: 12,
            width: (opts.left || 150) - 12,
            overflow: 'truncate'
          }
        },
        series: [{
          type: 'bar',
          barWidth: opts.barWidth || 10,
          data: items.map(i => i.value),
          itemStyle: {
            borderRadius: [0, 6, 6, 0],
            color: {
              type: 'linear',
              x: 0,
              y: 0,
              x2: 1,
              y2: 0,
              colorStops: [{
                offset: 0,
                color: opts.startColor || '#4d86f7'
              }, {
                offset: 1,
                color: opts.endColor || '#2f6fed'
              }]
            }
          },
          label: {
            show: true,
            position: 'right',
            color: '#606266',
            fontSize: 12,
            formatter: opts.valueFormatter ? p => opts.valueFormatter(p.value) : '{c}'
          }
        }]
      };
    }
    const rankingOption = computed(() => hbarOption(ranking.value.map(r => ({
      name: r.jobTitle || '-',
      value: Number(r.applyCount || 0)
    })), {
      left: 170,
      startColor: '#4d86f7',
      endColor: '#2f6fed'
    }));
    const collegeOption = computed(() => hbarOption(colleges.value.map(c => ({
      name: c.name || '未填写',
      value: Number(c.value || 0)
    })), {
      left: 120,
      startColor: '#6ea1f9',
      endColor: '#2f6fed'
    }));

    /* ---------------- 成功率 ---------------- */
    const successStates = computed(() => [{
      name: '成功投递',
      value: successData.value.success || 0,
      color: '#18a058'
    }, {
      name: '未通过',
      value: stateCount('rejected'),
      color: '#f56c6c'
    }, {
      name: '待处理',
      value: stateCount('pending'),
      color: '#909399'
    }, {
      name: '已撤回',
      value: stateCount('withdrawn'),
      color: '#d3dce6'
    }]);
    const successDonutOption = computed(() => donutOption(successStates.value.map(s => ({
      name: s.name,
      value: s.value,
      itemStyle: {
        color: s.color
      }
    }))));
    const successBarOption = computed(() => {
      const rates = [...(successData.value.jobTypeRates || [])].sort((a, b) => b.rate - a.rate);
      return hbarOption(rates.map(r => ({
        name: jobTypeLabel(r.jobType),
        value: Number(r.rate || 0)
      })), {
        left: 110,
        right: 70,
        barWidth: 12,
        valueFormatter: v => `${Number(v).toFixed(1)}%`
      });
    });

    /* ---------------- 生命周期 ---------------- */
    onMounted(async () => {
      await Promise.all([loadAll(), loadDict()]);
      refreshTimer = setInterval(loadAll, 60000);
      clockTimer = setInterval(() => {
        now.value = dayjs();
      }, 1000);
    });
    onUnmounted(() => {
      if (refreshTimer) clearInterval(refreshTimer);
      if (clockTimer) clearInterval(clockTimer);
    });
    const __returned__ = {
      dictStore,
      loading,
      loadError,
      trendDays,
      updateTime,
      now,
      summary,
      trend,
      ranking,
      jobTypes,
      colleges,
      companyAuth,
      successData,
      recent,
      jobTypeDict,
      fmt,
      get refreshTimer() {
        return refreshTimer;
      },
      set refreshTimer(v) {
        refreshTimer = v;
      },
      get clockTimer() {
        return clockTimer;
      },
      set clockTimer(v) {
        clockTimer = v;
      },
      loadAll,
      changeDays,
      loadDict,
      jobTypeLabel,
      stateLabel,
      stateCount,
      pct,
      tagClass,
      TAG_COLORS,
      tagColor,
      kpis,
      trendSum,
      trendAvg,
      trendOption,
      donutOption,
      APPLY_COLORS,
      APPLY_ORDER,
      applyStateOption,
      INTERVIEW_COLORS,
      INTERVIEW_ORDER,
      interviewStateOption,
      JOB_TYPE_COLORS,
      jobTypeOption,
      COMPANY_COLORS,
      companyAuthOption,
      hbarOption,
      rankingOption,
      collegeOption,
      successStates,
      successDonutOption,
      successBarOption,
      ref,
      computed,
      onMounted,
      onUnmounted,
      get dayjs() {
        return dayjs;
      },
      ChartBase,
      get screenDashboard() {
        return screenDashboard;
      },
      get screenApplyTrend() {
        return screenApplyTrend;
      },
      get screenJobRanking() {
        return screenJobRanking;
      },
      get screenJobTypeDistribution() {
        return screenJobTypeDistribution;
      },
      get screenCollegeDistribution() {
        return screenCollegeDistribution;
      },
      get screenCompanyAuthDistribution() {
        return screenCompanyAuthDistribution;
      },
      get screenApplySuccess() {
        return screenApplySuccess;
      },
      get screenRecentApplies() {
        return screenRecentApplies;
      },
      get useDictStore() {
        return useDictStore;
      },
      get APPLY_STATE_MAP() {
        return APPLY_STATE_MAP;
      },
      get INTERVIEW_STATE_MAP() {
        return INTERVIEW_STATE_MAP;
      },
      get COMPANY_AUTH_STATE_MAP() {
        return COMPANY_AUTH_STATE_MAP;
      },
      get formatDateTime() {
        return formatDateTime;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
